import { writable, get } from 'svelte/store';
import type { TransitionDirection } from '$lib/types';
import { userAccountData, diskSelectionData } from '$lib/store';
// @ts-expect-error — generated by Wails
import { CanGoNext, CanGoBack, SetCurrentPage, ValidateUserAccount, ValidateDiskSelection, RebootAndClose } from '@wails/go/app/App.js';

export type PageId = 0 | 1 | 2 | 3 | 4 | 5;

interface NavigationState {
	currentPage: PageId;
	isTransitioning: boolean;
	errorMessage: string | null;
}

function createNavigationStore() {
	const { subscribe, set, update } = writable<NavigationState>({
		currentPage: 0,
		isTransitioning: false,
		errorMessage: null,
	});

	return {
		subscribe,

		async goNext(): Promise<boolean> {
			const state = get(this);
			if (state.isTransitioning) return false;

			update((s) => ({ ...s, isTransitioning: true, errorMessage: null }));

			const success = await validateCurrentPage(state.currentPage);
			if (!success) {
				update((s) => ({ ...s, isTransitioning: false }));
				return false;
			}

			const canGo = await CanGoNext();
			if (!canGo) {
				update((s) => ({
					...s,
					isTransitioning: false,
					errorMessage: 'Validation failed. Please fix the issues above.',
				}));
				return false;
			}

			const nextPage = (state.currentPage + 1) as PageId;
			await SetCurrentPage(nextPage);
			update((s) => ({ ...s, currentPage: nextPage, isTransitioning: false }));
			return true;
		},

		async goBack(): Promise<boolean> {
			const state = get(this);
			if (state.isTransitioning || state.currentPage === 0) return false;

			// Reset disk selection when going back from ConfirmationPage
			if (state.currentPage === 3) {
				diskSelectionData.set({ diskId: '', disk: null });
			}

			update((s) => ({ ...s, isTransitioning: true, errorMessage: null }));

			const prevPage = (state.currentPage - 1) as PageId;
			await SetCurrentPage(prevPage);
			update((s) => ({ ...s, currentPage: prevPage, isTransitioning: false }));
			return true;
		},

		async finish(): Promise<void> {
			try {
				await RebootAndClose();
			} catch (err) {
				update((s) => ({
					...s,
					errorMessage: err instanceof Error ? err.message : 'Failed to reboot',
				}));
			}
		},

		resetError() {
			update((s) => ({ ...s, errorMessage: null }));
		},

		setInitialPage(page: PageId) {
			update((s) => ({ ...s, currentPage: page }));
		},
	};
}

async function validateCurrentPage(page: number): Promise<boolean> {
	try {
		if (page === 1) {
			const data = get(userAccountData);
			await ValidateUserAccount({
				username: data.username,
				password: data.password,
				confirmPassword: data.confirmPassword,
			});
		}

		if (page === 2) {
			const data = get(diskSelectionData);
			await ValidateDiskSelection({ diskId: data.diskId });
		}

		return true;
	} catch {
		return false;
	}
}

export const navigation = createNavigationStore();
